export function compileApprovedPlan(project: Project): string {
  const unresolved = project.sections.filter((section) => section.status !== "APPROVED");
  if (unresolved.length) throw new WorkflowConflict(`Plan has ${unresolved.length} unresolved section(s).`);
  return project.sections
    .toSorted((left, right) => left.order - right.order)
    .map((section) => `## ${section.title}\n\n${section.content}`)
    .join("\n\n");
}

import { payloadHash, type Project } from "./model.ts";
import { AtomicProjectStore, RevisionConflict } from "../store/atomic-project-store.ts";

export interface ActionResult {
  project: Project;
  duplicate: boolean;
}

export class WorkflowService {
  constructor(private readonly store: AtomicProjectStore) {}

  async execute(
    actionId: string,
    payload: unknown,
    expectedRevision: number,
    mutation: (project: Project) => Project,
  ): Promise<ActionResult> {
    const loaded = await this.store.load();
    const hash = payloadHash(payload);
    const existing = loaded.state.actions.find((action) => action.id === actionId);
    if (existing) {
      if (existing.payloadHash !== hash) throw new RevisionConflict("Action ID was already used with a different payload.");
      return { project: loaded.state, duplicate: true };
    }
    if (loaded.state.revision !== expectedRevision) {
      throw new RevisionConflict(`Expected revision ${expectedRevision}, found ${loaded.state.revision}.`);
    }
    const next = mutation(loaded.state);
    next.actions.push({ id: actionId, payloadHash: hash, resultRevision: expectedRevision + 1 });
    return { project: await this.store.save(expectedRevision, next), duplicate: false };
  }
}

import assert from "node:assert/strict";
import test from "node:test";
import { approveSection, compileApprovedPlan, reviseSection, WorkflowConflict } from "../src/server/workflow/transitions.ts";
import { createProject } from "../src/server/workflow/model.ts";

function approve(project: ReturnType<typeof createProject>, id: string, content = `${id} content`) {
  const drafted = reviseSection(project, id, content);
  const section = drafted.sections.find((item) => item.id === id)!;
  return approveSection(drafted, id, section.version, section.hash);
}

test("advances only after exact current-version approval", () => {
  const drafted = reviseSection(createProject("/workspace"), "control", "scope v1");
  const section = drafted.sections[0];
  assert.throws(() => approveSection(drafted, "control", section.version, "stale"), WorkflowConflict);
  const approved = approveSection(drafted, "control", section.version, section.hash);
  assert.equal(approved.currentSectionId, "architecture");
});

test("upstream revision invalidates only transitive dependents", () => {
  let project = createProject("/workspace");
  for (const section of project.sections) project = approve(project, section.id);
  project = reviseSection(project, "tools", "changed tools");
  assert.equal(project.sections.find((item) => item.id === "experience")?.status, "APPROVED");
  assert.equal(project.sections.find((item) => item.id === "verification")?.status, "STALE");
  assert.equal(project.sections.find((item) => item.id === "readiness")?.status, "STALE");
});

test("compiles exact approved blocks only", () => {
  let project = createProject("/workspace");
  assert.throws(() => compileApprovedPlan(project), WorkflowConflict);
  for (const section of project.sections) project = approve(project, section.id, `approved ${section.id}`);
  const plan = compileApprovedPlan(project);
  assert.match(plan, /approved control/);
  assert.match(plan, /approved readiness/);
});

import { randomUUID } from "node:crypto";
import { operationSchema, payloadHash, type Operation } from "../workflow/model.ts";

export function queueOperation(payload: unknown): Operation {
  return operationSchema.parse({
    id: randomUUID(),
    payloadHash: payloadHash(payload),
    nativeSessionId: null,
    nativeMessageId: null,
    status: "QUEUED",
    result: null,
  });
}

export function markDisconnected(operation: Operation): Operation {
  if (["SUCCEEDED", "FAILED", "CANCELLED"].includes(operation.status)) return operation;
  return operationSchema.parse({ ...operation, status: "UNKNOWN", result: "Disconnected; reconcile native state before retry." });
}

export function reconcileOperation(
  operation: Operation,
  native: { sessionId: string; messageId?: string; status: "running" | "waiting_permission" | "succeeded" | "failed" | "cancelled"; result?: string },
): Operation {
  const statuses = {
    running: "RUNNING",
    waiting_permission: "WAITING_PERMISSION",
    succeeded: "SUCCEEDED",
    failed: "FAILED",
    cancelled: "CANCELLED",
  } as const;
  return operationSchema.parse({
    ...operation,
    nativeSessionId: native.sessionId,
    nativeMessageId: native.messageId ?? operation.nativeMessageId,
    status: statuses[native.status],
    result: native.result ?? null,
  });
}

import assert from "node:assert/strict";
import { mkdtemp, readFile, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import test from "node:test";
import { AtomicProjectStore, RevisionConflict } from "../src/server/store/atomic-project-store.ts";
import { createProject } from "../src/server/workflow/model.ts";
import { WorkflowService } from "../src/server/workflow/service.ts";
import { reviseSection } from "../src/server/workflow/transitions.ts";

test("persists one idempotent action and rejects conflicting reuse", async () => {
  const directory = await mkdtemp(join(tmpdir(), "ub-store-"));
  const store = new AtomicProjectStore(join(directory, "project.json"));
  await store.initialize(createProject("/workspace"));
  const service = new WorkflowService(store);
  const first = await service.execute("action-1", { content: "v1" }, 0, (project) => reviseSection(project, "control", "v1"));
  assert.equal(first.project.revision, 1);
  const duplicate = await service.execute("action-1", { content: "v1" }, 0, (project) => project);
  assert.equal(duplicate.duplicate, true);
  await assert.rejects(
    service.execute("action-1", { content: "different" }, 1, (project) => project),
    RevisionConflict,
  );
});

test("offers previous snapshot without overwriting corrupt current data", async () => {
  const directory = await mkdtemp(join(tmpdir(), "ub-recovery-"));
  const path = join(directory, "project.json");
  const store = new AtomicProjectStore(path);
  await store.initialize(createProject("/workspace"));
  await store.save(0, reviseSection((await store.load()).state, "control", "v1"));
  await writeFile(path, "{corrupt", "utf8");
  const recovered = await store.load();
  assert.equal(recovered.source, "previous");
  assert.equal(recovered.corruptPath, path);
  assert.equal(await readFile(path, "utf8"), "{corrupt");
});

